// Texto de exibição: tira saudação e fecho de e-mail copiado no histórico, para o relatório mostrar o que foi feito.
function resumoExibicao(txt, tipo) {
  var bruto = String(txt || ""), t = bruto.replace(/\s+/g, " ").trim();
  if (/^EVENTO/.test(norm(tipo))) { var ev = /^(.+?)\s+-\s+Realizado:/i.exec(t); if (ev) return ev[1] + " (realizado)"; }
  t = t.replace(/^Prezad[oa]s?(?:\([oa]s?\))?\s+Senhor[a-z]*(?:\([oa]s?\))?\s+[^,]{0,90},\s*/i, "");
  t = t.replace(/\s*(?:Permanecemos|Seguimos|Ficamos)\s+à\s+disposição[^.]*\.?\s*(?:At\.?te\.?|Atenciosamente\.?)?\s*$/i, "");
  t = t.replace(/\s*(?:At\.?te\.?|Atenciosamente\.?)\s*$/i, "");
  if (t.length > 170) {   // corta no fim de uma frase (até 170 caracteres, o que cabe nas 3 linhas do cartão), sem deixar o texto pela metade
    var corte = 0, rs = /[.!?]\s+/g, mm;
    while ((mm = rs.exec(t)) && mm.index + 1 <= 170) corte = mm.index + 1;
    t = corte ? t.slice(0, corte) : t.slice(0, 167).replace(/\s+\S*$/, "") + "…";
  }
  return t || bruto;
}
