function agendamentosDoTexto(atividades, hoje) {
  var MES = { JANEIRO: 1, FEVEREIRO: 2, MARCO: 3, ABRIL: 4, MAIO: 5, JUNHO: 6, JULHO: 7, AGOSTO: 8, SETEMBRO: 9, OUTUBRO: 10, NOVEMBRO: 11, DEZEMBRO: 12 };
  var ref = hoje || new Date(), base = Date.UTC(ref.getUTCFullYear(), ref.getUTCMonth(), ref.getUTCDate()), out = [], vistos = {};
  (atividades || []).forEach(function (a) {
    var t = norm(a.descricao).replace(/\s+/g, " ");
    var re = /(?:DATA\s+E\s+HORARIO|AGENDAD[OA]\w*)[^.]{0,120}?\b(\d{1,2})\s+DE\s+(JANEIRO|FEVEREIRO|MARCO|ABRIL|MAIO|JUNHO|JULHO|AGOSTO|SETEMBRO|OUTUBRO|NOVEMBRO|DEZEMBRO)\s+DE\s+(\d{4})(?:\s*,?\s*AS\s+(\d{1,2})\s*H\s*(\d{2})?)?/, m = re.exec(t);
    if (!m) return;
    var d = +m[1], mo = MES[m[2]], y = +m[3];
    if (Date.UTC(y, mo - 1, d) < base) return;
    var data = ("0" + d).slice(-2) + "/" + ("0" + mo).slice(-2) + "/" + y, hora = m[4] ? (" às " + m[4] + "h" + (m[5] || "00")) : "";
    var quem = /COMITE/.test(t) ? "Reunião do Comitê de Credores" : "Reunião", k = data + "|" + quem;
    if (vistos[k]) return; vistos[k] = 1;
    out.push({ descricao: quem + " agendada" + hora + " (conforme registro de " + (a.data || "data não informada") + ")", data: data, responsavel: "", numero_processo: a.numero_processo });
  });
  return out;
}

